# Prepare-StpExport.ps1 - ONE COMMAND for the STP side of an end-to-end check (STP-976 after STP-962; the STP-883 capstone
# was the hand-run prototype, docs/experiments/CAPSTONE_STP883_2026-10-13.md):
#   1. a FRESH clone of hyssostech/STP at -StpRef, built as image stp-server:<sha8> (skipped when the image exists);
#   2. a container (-ContainerName) on NON-default host ports, its C2SIM bridge pointed at the private server;
#   3. the scenario .op loaded (optionally with unit attributes stripped - STP-1104's `role`), the Initialization and
#      Order GENERATED by the bridge (tools\stp\StpPush.ps1 -Action regen, all affiliations);
#   4. offline checks: xsd validation of both files against the clone's C2SIM_SMX_LOX_CWIX2024.xsd, and the deployed
#      interface's --parse-order on the Order (the B1 table);
#   5. a summary, and the exact push lines for after the VR-Forces launch (DEMO_RUNBOOK 2.1-2.4).
# It pushes NOTHING to the C2SIM server and launches nothing of VR-Forces. -WhatIf prints the plan and touches nothing.
# It only ever removes a container named -ContainerName (its own). ASCII only.
# Exit: 0 all steps ok (xsd failures are REPORTED, not fatal); 1 a step failed; 2 usage / precondition.
param(
    [string]$StpRef = 'origin/main',
    [string]$Op = 'D:\C2SIM-preserve\ironstorm-narrative1\STP-IRON-STORM-SYNTHETIC_Narrative1.op',
    [string[]]$StripUnitAttributes = @('role'),
    [string]$OutDir = '',
    [string]$SrcDir = (Join-Path $env:LOCALAPPDATA 'VrfC2Sim\stp-src'),
    [string]$ContainerName = 'stp976-vrf',
    [int]$MgmtPort = 39500,
    [int]$RestPort = 39575,
    [int]$WsPort = 39599,
    [string]$C2SimRestUrl = 'http://host.docker.internal:18080/C2SIMServer',
    [string]$C2SimStompUrl = 'http://host.docker.internal:61614/topic/C2SIM',
    [switch]$WhatIf
)
$ErrorActionPreference = 'Stop'
$Repo = Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
if (-not $OutDir) { $OutDir = Join-Path $Repo ('runs\stp-export\' + (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ')) }
foreach ($p in $MgmtPort, $RestPort, $WsPort) {
    if (($p -ge 9500 -and $p -le 9599) -or ($p -ge 19500 -and $p -le 19620)) {
        Write-Host "[FAIL] port $p is in a range other sessions use (9500-9599 stp-lt, 19500-19620); pick another."; exit 2
    }
}
$plan = @(
    "STP source : $SrcDir (fresh clone or fetch of hyssostech/STP), checkout $StpRef",
    "image      : stp-server:<sha8 of $StpRef> (docker build; skipped if present)",
    "container  : $ContainerName on 127.0.0.1:$MgmtPort/$RestPort/$WsPort -> bridge REST $C2SimRestUrl STOMP $C2SimStompUrl",
    ("scenario   : $Op" + $(if ($StripUnitAttributes.Count) { " (unit attributes stripped: $($StripUnitAttributes -join ', '))" } else { '' })),
    "export     : StpPush.ps1 -Action regen (all affiliations) -> $OutDir",
    "checks     : xsd (clone's C2SIM_SMX_LOX_CWIX2024.xsd) on both files; VrfC2SimApp --parse-order on the Order")
Write-Host '=== Prepare-StpExport plan ==='
$plan | ForEach-Object { Write-Host "  $_" }
if ($WhatIf) { Write-Host 'WhatIf: nothing done.'; exit 0 }
if (-not (Test-Path $Op)) { Write-Host "[FAIL] scenario not found: $Op"; exit 2 }
New-Item -ItemType Directory -Force $OutDir | Out-Null

function Step([string]$name, [scriptblock]$body) {
    Write-Host "--- $name"
    try { & $body } catch { Write-Host "[FAIL] $name : $($_.Exception.Message)"; exit 1 }
}

$sha = ''
Step 'source' {
    if (-not (Test-Path (Join-Path $SrcDir '.git'))) {
        git clone --quiet https://github.com/hyssostech/STP.git $SrcDir 2>&1 | Out-Null
        if ($LASTEXITCODE -ne 0) { throw 'git clone failed' }
    }
    git -C $SrcDir fetch --quiet origin 2>&1 | Out-Null
    git -C $SrcDir checkout --quiet --detach $StpRef 2>&1 | Out-Null
    if ($LASTEXITCODE -ne 0) { throw "checkout $StpRef failed" }
    $script:sha = (git -C $SrcDir rev-parse HEAD).Trim()
    Write-Host "[OK] STP $StpRef = $($script:sha)"
}
$image = 'stp-server:' + $sha.Substring(0, 8)
Step 'image' {
    docker image inspect $image *> $null
    if ($LASTEXITCODE -eq 0) { Write-Host "[OK] image $image exists - not rebuilt"; return }
    docker build -t $image $SrcDir *> (Join-Path $OutDir 'docker-build.log')
    if ($LASTEXITCODE -ne 0) { throw "docker build failed (docker-build.log)" }
    Write-Host "[OK] built $image"
}
Step 'container' {
    if (docker ps -a --filter "name=^$ContainerName$" --format '{{.Names}}') { docker rm -f $ContainerName | Out-Null }
    docker run -d --name $ContainerName --restart no --add-host=host.docker.internal:host-gateway `
        -p "127.0.0.1:${MgmtPort}:9500" -p "127.0.0.1:${RestPort}:9575" -p "127.0.0.1:${WsPort}:9599" `
        -e "STP_C2SimBridge__App__RestUrl=$C2SimRestUrl" -e "STP_C2SimBridge__App__StompUrl=$C2SimStompUrl" `
        -e 'STP_Nucleus__Deployment__FileTraceLevel=Debug' $image | Out-Null
    if ($LASTEXITCODE -ne 0) { throw 'docker run failed' }
    $deadline = (Get-Date).AddSeconds(240)
    while ((Get-Date) -lt $deadline) {
        try { $st = Invoke-RestMethod "http://127.0.0.1:$MgmtPort/api/mgmt/status" -TimeoutSec 5 } catch { $st = $null }
        if ($st -and $st.engineState -eq 'Running') { Write-Host "[OK] $ContainerName engineState Running"; return }
        Start-Sleep 5
    }
    throw "engine not Running within 240 s (docker logs $ContainerName)"
}
$opToLoad = $Op
Step 'scenario' {
    if ($StripUnitAttributes.Count) {
        $script:opToLoad = Join-Path $OutDir 'scenario_stripped.op'
        $line = & python -I (Join-Path $PSScriptRoot 'strip_op_unit_attrs.py') $Op $script:opToLoad @StripUnitAttributes
        if ($LASTEXITCODE -ne 0) { throw 'strip_op_unit_attrs.py failed' }
        Write-Host "[OK] stripped: $line"
    }
}
Step 'export' {
    & pwsh -NoProfile -File (Join-Path $PSScriptRoot 'StpPush.ps1') -Action regen -File $opToLoad -Url "ws://127.0.0.1:$WsPort" `
        -ScenarioName 'STP-EXPORT' -OutDir $OutDir *> (Join-Path $OutDir 'regen.log')
    if ($LASTEXITCODE -ne 0) { throw "regen failed (regen.log: $((Get-Content (Join-Path $OutDir 'regen.log') -Tail 1)))" }
    Write-Host '[OK] Initialization and Order generated'
}
$init = Join-Path $OutDir 'REGEN-STP-EXPORT_initialization.xml'
$order = Join-Path $OutDir 'REGEN-STP-EXPORT_order.xml'
Step 'xsd' {
    $xsd = Get-ChildItem $SrcDir -Recurse -Filter 'C2SIM_SMX_LOX_CWIX2024.xsd' | Select-Object -First 1
    if (-not $xsd) { Write-Host '[WARN] no C2SIM_SMX_LOX_CWIX2024.xsd in the clone - xsd NOT checked'; return }
    foreach ($f in $init, $order) {
        $errs = New-Object System.Collections.Generic.List[string]
        $set = New-Object System.Xml.XmlReaderSettings
        $set.ValidationType = 'Schema'
        $null = $set.Schemas.Add('http://www.sisostds.org/schemas/C2SIM/1.1', $xsd.FullName)
        $set.add_ValidationEventHandler({ param($s, $e) $errs.Add("L$($e.Exception.LineNumber): $($e.Message)") })
        $r = [System.Xml.XmlReader]::Create($f, $set)
        try { while ($r.Read()) {} } finally { $r.Close() }
        if ($errs.Count) { Write-Host "[WARN] xsd FAIL $(Split-Path $f -Leaf): $($errs.Count) error(s), first: $($errs[0])" }
        else { Write-Host "[OK] xsd PASS $(Split-Path $f -Leaf)" }
    }
}
Step 'parse-order' {
    $exe = Join-Path $Repo 'src\VrfC2SimApp\bin\Release-5.2\net10.0\win-x64\VrfC2SimApp.exe'
    $env:PATH = 'C:\MAK\vrforces5.2d\bin64;C:\MAK\vrlink5.10\bin64;C:\MAK\makRti5.0.1\bin;' + $env:PATH
    & $exe --parse-order $order *> (Join-Path $OutDir 'b1-parse-order.txt')
    if ($LASTEXITCODE -ne 0) { throw "--parse-order exit $LASTEXITCODE (b1-parse-order.txt)" }
    $b1 = Get-Content (Join-Path $OutDir 'b1-parse-order.txt')
    Write-Host ("[OK] B1: " + (($b1 | Select-String '^Tasks:').Line) + "; " + (($b1 | Select-String 'durations decoded:').Line).Trim())
}
Write-Host '=== done ==='
Write-Host "  files : $init"
Write-Host "          $order"
Write-Host "  NEXT  : launch per DEMO_RUNBOOK 1.3-2.2 (-ClientId STP -Server private), then push from THIS container:"
Write-Host "    pwsh -NoProfile -File tools\stp\StpPush.ps1 -Action initialization -File `"$init`" -Url ws://127.0.0.1:$WsPort"
Write-Host "    pwsh -NoProfile -File tools\stp\StpPush.ps1 -Action order -File `"$order`" -Url ws://127.0.0.1:$WsPort"
Write-Host "  afterwards: docker rm -f $ContainerName"
exit 0
